<script setup lang="ts">import{computed}from'vue';import{VALUE_KEYS,type ConditionDirection,type ConditionMetric,type MustCondition}from'../../core/models';import{CONDITION_RANGES,findConditionConflicts,metricLabel}from'../../core/gate-service';const props=defineProps<{conditions:MustCondition[]}>();const emit=defineEmits<{add:[];update:[id:string,p:Partial<MustCondition>];remove:[id:string]}>();const metrics:ConditionMetric[]=[...VALUE_KEYS,'reversibility'];const conflicts=computed(()=>findConditionConflicts(props.conditions));const range=(metric:ConditionMetric)=>CONDITION_RANGES[metric];function setMetric(id:string,event:Event){emit('update',id,{metric:(event.target as HTMLSelectElement).value as ConditionMetric})}function setDirection(id:string,event:Event){emit('update',id,{direction:(event.target as HTMLSelectElement).value as ConditionDirection})}function setValue(id:string,event:Event){emit('update',id,{value:Number((event.target as HTMLInputElement).value)})}function setEnabled(id:string,event:Event){emit('update',id,{enabled:(event.target as HTMLInputElement).checked})}function setNote(id:string,event:Event){emit('update',id,{note:(event.target as HTMLInputElement).value})}</script>
<template><section class="paper-panel conditions"><span class="index">03 / MUST-HAVE</span><h2>哪些底线不能妥协？</h2><p class="cond-intro">必须条件不能被其他优点抵消：明确违反的方案不参与推荐；指标缺失或落入临界带（影响 ±0.5、可逆性 ±5%）的方案保留为条件候选，确认前只作暂定推荐。关闭全部条件即回到纯评分结果。</p><article v-for="condition in conditions" :key="condition.id" class="cond-row" :class="{off:!condition.enabled}"><div class="cond-main"><select :value="condition.metric" @change="setMetric(condition.id,$event)"><option v-for="metric in metrics" :key="metric" :value="metric">{{metricLabel(metric)}}</option></select><select :value="condition.direction" @change="setDirection(condition.id,$event)"><option value="atLeast">不低于</option><option value="atMost">不高于</option></select><input type="number" :min="range(condition.metric)[0]" :max="range(condition.metric)[1]" :step="condition.metric==='reversibility'?5:0.5" :value="condition.value" @input="setValue(condition.id,$event)"><label class="cond-toggle"><input type="checkbox" :checked="condition.enabled" @change="setEnabled(condition.id,$event)">启用</label><button type="button" aria-label="删除条件" @click="emit('remove',condition.id)">×</button></div><input class="cond-note" :value="condition.note" placeholder="依据：为什么这是底线？（会随案例保存并写入报告）" @input="setNote(condition.id,$event)"></article><div v-if="conflicts.length" class="cond-conflicts"><p v-for="conflict in conflicts" :key="conflict">{{conflict}}</p></div><button type="button" class="cond-add" :disabled="conditions.length>=6" @click="emit('add')">＋ 添加必须条件</button></section></template>
